import type { RecipeSeed } from './recipes'

export const recipeFinalSeeds: RecipeSeed[] = [
  {"id":"thai-chicken-khao-soi","sourceId":"slice4-01","name":"ข้าวซอยไก่แบบเบา","englishName":"Thai Chicken Khao Soi","category":"Thai favorites","cuisine":"Thai","servings":2,"prepMinutes":20,"cookMinutes":25,"ingredients":[{"item":"Skinless chicken breast, sliced","amount":"260 g"},{"item":"Whole-wheat noodles, dry, divided","amount":"170 g"},{"item":"Light coconut milk","amount":"200 ml"},{"item":"Low-sodium stock","amount":"400 ml"},{"item":"Red curry paste","amount":"2 tbsp"},{"item":"Curry powder","amount":"2 tsp"},{"item":"Neutral oil","amount":"2 tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Red onion, thinly sliced","amount":"¼ cup"},{"item":"Coriander leaves, chopped","amount":"2 tbsp"}],"instructions":["Cook 20 g of the dry noodles until just pliable, drain and pat very dry. Toss with 1 teaspoon oil, spread loosely on a tray and bake at 200°C for 10–15 minutes until crisp; reserve for garnish.","Warm the remaining 1 teaspoon oil in a pot; fry curry paste and curry powder for 1 minute. Add coconut milk and stock and simmer for 5 minutes.","Add chicken and gently poach until its thickest piece reaches 74°C. Separately cook the remaining 150 g dry noodles according to the packet and drain.","Divide the cooked noodles and broth between two bowls. Finish with lime juice, red onion, coriander and half the crispy noodles on each bowl."],"nutrition":{"kcal":611,"protein":43,"carbs":67,"fat":18,"fiber":9,"sodium":930},"tags":["High protein","Comforting","Balanced"],"accent":"gold"},
  { id:'thai-prawn-omelet-herb-salad', sourceId:'slice4-02', name:'ไข่เจียวกุ้งกับสลัดสมุนไพร', englishName:'Thai Prawn Omelet with Herb Salad', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:10, ingredients:[{item:'Prawns, peeled',amount:'220 g'},{item:'Eggs',amount:'4'},{item:'Fish sauce',amount:'1 tsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Cherry tomatoes',amount:'120 g'},{item:'Mint leaves',amount:'½ cup'},{item:'Coriander leaves',amount:'½ cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Beat the eggs with fish sauce and fold in the prawns.','Heat the oil in a non-stick pan, pour in the egg mixture, cover and cook over medium-low heat until the centre is set and the prawns are opaque; fold and divide.','Toss cucumber, tomatoes and herbs with lime juice.','Serve the omelet with the herb salad and jasmine rice.'], nutrition:{kcal:390,protein:35,carbs:31,fat:15,fiber:3,sodium:560}, tags:['High protein','Quick','Gluten-free'], accent:'coral' },
  {"id":"thai-tofu-panang-curry","sourceId":"slice4-03","name":"แกงพะแนงเต้าหู้","englishName":"Thai Tofu Panang Curry","category":"Thai favorites","cuisine":"Thai","servings":2,"prepMinutes":12,"cookMinutes":18,"ingredients":[{"item":"Firm tofu, cubed","amount":"300 g"},{"item":"Red curry paste, vegetarian-certified Panang style","amount":"2 tbsp"},{"item":"Light coconut milk","amount":"200 ml"},{"item":"Bell pepper, sliced","amount":"1 medium"},{"item":"Green beans, cut","amount":"150 g"},{"item":"Natural peanut butter","amount":"2 tbsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Thai basil leaves","amount":"½ cup"},{"item":"Jasmine rice, cooked","amount":"1 cup"},{"item":"Ground cumin","amount":"½ tsp"}],"instructions":["Simmer 3 tablespoons of the coconut milk with the vegetarian Panang paste and cumin for 2 minutes, then whisk in peanut butter and the remaining coconut milk.","Add green beans and bell pepper; simmer uncovered for 8–10 minutes until crisp-tender and the sauce is thick.","Fold in tofu and soy sauce and heat gently for 4 minutes; the reduced sauce should cling to the tofu rather than form a soup.","Turn off the heat, add lime juice and Thai basil, and serve with jasmine rice."],"nutrition":{"kcal":488,"protein":27,"carbs":42,"fat":25,"fiber":8,"sodium":940},"tags":["Vegetarian","Plant protein","Balanced"],"accent":"lime"},
  { id:'thai-beef-nam-tok', sourceId:'slice4-04', name:'น้ำตกเนื้อย่างกับข้าวกล้อง', englishName:'Thai Beef Nam Tok with Brown Rice', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Lean beef strips',amount:'280 g'},{item:'Cabbage, shredded',amount:'180 g'},{item:'Mint leaves',amount:'½ cup'},{item:'Shallot, sliced',amount:'¼ cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Fish sauce',amount:'1½ tsp'},{item:'Toasted rice powder',amount:'1 tbsp'},{item:'Dried chilli flakes',amount:'½ tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Grill or sear the beef over high heat until browned and cooked to the desired doneness; rest for 5 minutes, then slice thinly.','Mix lime juice, fish sauce and chilli flakes in a bowl.','Toss the warm beef with the dressing, shallot, mint and toasted rice powder.','Serve with shredded cabbage and brown rice.'], nutrition:{kcal:405,protein:37,carbs:40,fat:12,fiber:5,sodium:560}, tags:['High protein','Gluten-free','Balanced'], accent:'red' },
  {"id":"thai-mushroom-tom-kha","sourceId":"slice4-05","name":"ต้มข่าเห็ดแบบเบา","englishName":"Thai Mushroom Tom Kha","category":"Plant-forward","cuisine":"Thai","servings":2,"prepMinutes":12,"cookMinutes":16,"ingredients":[{"item":"Mixed mushrooms, sliced","amount":"300 g"},{"item":"Light coconut milk","amount":"200 ml"},{"item":"Low-sodium vegetable stock","amount":"500 ml"},{"item":"Lemongrass, bruised","amount":"1 stalk"},{"item":"Galangal, sliced","amount":"1 tbsp"},{"item":"Cherry tomatoes","amount":"120 g"},{"item":"Lime juice","amount":"2 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Coriander leaves","amount":"½ cup"}],"instructions":["Simmer vegetable stock with lemongrass and galangal for 5 minutes.","Add coconut milk, mushrooms and tomatoes and gently simmer for 8–10 minutes until the mushrooms are tender.","Remove the tough lemongrass and galangal slices, season with soy sauce and turn off the heat.","Add lime juice and coriander immediately before serving."],"nutrition":{"kcal":149,"protein":8,"carbs":15,"fat":8,"fiber":3,"sodium":530},"tags":["Vegan","Light","Comforting"],"accent":"violet"},
  { id:'thai-steamed-tofu-lime', sourceId:'slice4-06', name:'เต้าหู้นึ่งมะนาวสมุนไพร', englishName:'Thai Steamed Tofu with Lime Herbs', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:10, cookMinutes:12, ingredients:[{item:'Firm tofu, sliced',amount:'300 g'},{item:'Chinese cabbage, chopped',amount:'200 g'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Lime juice',amount:'2 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Bird’s eye chilli, sliced',amount:'1'},{item:'Coriander leaves',amount:'½ cup'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Arrange cabbage, mushrooms and tofu on a heatproof plate and steam until the vegetables are tender and the tofu is hot.','Mix garlic, lime juice, soy sauce and chilli into a sharp dressing.','Spoon the dressing over the steamed tofu and vegetables.','Finish with coriander and serve with jasmine rice.'], nutrition:{kcal:340,protein:21,carbs:42,fat:10,fiber:5,sodium:640}, tags:['Vegan','Light','Plant protein'], accent:'aqua' },
  {"id":"japanese-pork-yaki-udon","sourceId":"slice4-07","name":"ยากิอุด้งหมูและผัก","englishName":"Japanese Pork Yaki Udon","category":"Quick meals","cuisine":"Japanese","servings":2,"prepMinutes":15,"cookMinutes":14,"ingredients":[{"item":"Lean pork loin, thinly sliced","amount":"260 g"},{"item":"Whole-wheat udon, cooked","amount":"300 g"},{"item":"Cabbage, shredded","amount":"200 g"},{"item":"Carrot, julienned","amount":"1 small"},{"item":"Mushrooms, sliced","amount":"150 g"},{"item":"Ginger, grated","amount":"1 tsp"},{"item":"White miso","amount":"1 tbsp"},{"item":"Sesame oil","amount":"1 tsp"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Rice vinegar","amount":"1 tbsp"}],"instructions":["Loosen the cooked udon with hot water and drain. Whisk miso and rice vinegar with 2 tablespoons water.","Sear pork in half the sesame oil in a wide pan until browned; remove to a clean plate.","Add remaining oil and sear mushrooms undisturbed for 3 minutes. Add cabbage, carrot and ginger and stir-fry for 3 minutes.","Return pork, add udon and miso mixture and toss until the pork is cooked through and the thick noodles are lightly glazed. Finish with spring onion."],"nutrition":{"kcal":474,"protein":38,"carbs":54,"fat":11,"fiber":8,"sodium":580},"tags":["High protein","Quick","Balanced"],"accent":"red"},
  { id:'japanese-shioyaki-salmon-sweet-potato', sourceId:'slice4-08', name:'แซลมอนย่างเกลือกับมันหวาน', englishName:'Japanese Shioyaki Salmon with Sweet Potato', category:'High protein', cuisine:'Japanese', servings:2, prepMinutes:10, cookMinutes:22, ingredients:[{item:'Salmon fillets',amount:'280 g'},{item:'Sweet potato, cubed',amount:'300 g'},{item:'Green beans',amount:'180 g'},{item:'Fine salt',amount:'¼ tsp'},{item:'Lemon',amount:'½'},{item:'Sesame seeds',amount:'1 tsp'},{item:'Neutral oil',amount:'1 tsp'}], instructions:['Toss the sweet potato with oil and half the salt, then roast at 200°C until tender and browned, about 18 minutes.','Season the salmon with the remaining salt and roast or grill until it flakes easily in the centre.','Steam the green beans until tender-crisp.','Serve salmon with sweet potato and beans, finishing with lemon and sesame.'], nutrition:{kcal:450,protein:31,carbs:42,fat:17,fiber:7,sodium:420}, tags:['High protein','Omega-rich','Gluten-free'], accent:'gold' },
  {"id":"japanese-baked-chicken-katsu","sourceId":"slice4-09","name":"ไก่คัตสึอบกับกะหล่ำปลีงา","englishName":"Japanese Baked Chicken Katsu with Sesame Cabbage","category":"Quick meals","cuisine":"Japanese","servings":2,"prepMinutes":18,"cookMinutes":22,"ingredients":[{"item":"Skinless chicken breast","amount":"300 g"},{"item":"Whole-wheat bread, crumbed","amount":"2 slices"},{"item":"Eggs","amount":"1"},{"item":"Cabbage, shredded","amount":"250 g"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Rice vinegar","amount":"1 tbsp"},{"item":"Neutral oil","amount":"1 tsp"}],"instructions":["Toast the bread crumbs with the oil in a pan until lightly golden. Pound chicken to an even 1.5 cm thickness and season with 1 teaspoon of the soy sauce.","Dip chicken in beaten egg, coat with crumbs and bake at 210°C until browned and the thickest part reaches 74°C, about 18–20 minutes.","Toss cabbage with the remaining 2 teaspoons soy sauce, rice vinegar and sesame seeds; no creamy dressing is needed.","Rest chicken for 3 minutes, slice and serve with sesame cabbage."],"nutrition":{"kcal":360,"protein":44,"carbs":21,"fat":11,"fiber":6,"sodium":500},"tags":["High protein","Balanced","Meal prep"],"accent":"aqua"},
  { id:'japanese-miso-eggplant-tofu', sourceId:'slice4-10', name:'มะเขือยาวมิโสะกับเต้าหู้', englishName:'Japanese Miso Eggplant with Tofu', category:'Plant-forward', cuisine:'Japanese', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Firm tofu, cubed',amount:'260 g'},{item:'Eggplant, sliced',amount:'300 g'},{item:'White miso',amount:'1½ tbsp'},{item:'Brown sugar',amount:'1 tsp'},{item:'Ginger, grated',amount:'1 tsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Rice vinegar',amount:'1 tbsp'}], instructions:['Whisk miso, brown sugar, ginger and rice vinegar with 2 tablespoons of water to make the glaze.','Pan-sear the eggplant with half the sesame oil until soft and browned; set aside.','Use the remaining oil to brown the tofu, then return the eggplant and add the glaze, tossing until it clings.','Serve over brown rice and finish with spring onion.'], nutrition:{kcal:390,protein:22,carbs:51,fat:12,fiber:9,sodium:650}, tags:['Vegetarian','Plant protein','Fiber-rich'], accent:'violet' },
  { id:'japanese-sesame-chicken-cabbage-tray', sourceId:'slice4-11', name:'ไก่อบมิโสะงากับกะหล่ำปลี', englishName:'Japanese Sesame Chicken and Cabbage Tray', category:'High protein', cuisine:'Japanese', servings:2, prepMinutes:12, cookMinutes:25, ingredients:[{item:'Skinless chicken thighs, boneless',amount:'300 g'},{item:'Napa cabbage, chopped',amount:'300 g'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Sweet potato, cubed',amount:'250 g'},{item:'White miso',amount:'1 tbsp'},{item:'Rice vinegar',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Whisk miso, rice vinegar and sesame oil into a glaze.','Arrange sweet potato, cabbage and mushrooms on a tray and roast at 200°C for 12 minutes.','Add the chicken, brush with the glaze and roast until the chicken is fully cooked and the vegetables are tender, about 12–15 minutes more.','Rest the chicken briefly, slice and finish the tray with sesame seeds.'], nutrition:{kcal:455,protein:34,carbs:43,fat:16,fiber:7,sodium:610}, tags:['High protein','Meal prep','Balanced'], accent:'lime' },
  { id:'korean-beef-daikon-soup', sourceId:'slice4-12', name:'ซุปเนื้อหัวไชเท้าเกาหลี', englishName:'Korean Beef and Daikon Soup', category:'Light bowls', cuisine:'Korean', servings:2, prepMinutes:10, cookMinutes:22, ingredients:[{item:'Lean beef strips',amount:'240 g'},{item:'Daikon, thickly sliced',amount:'300 g'},{item:'Low-sodium stock',amount:'650 ml'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Warm sesame oil in a pot and cook garlic until fragrant.','Add beef and sear briefly, then pour in the stock and add daikon. Simmer until the beef is cooked through and the daikon is tender.','Season with soy sauce and skim any foam from the surface.','Finish with spring onion and serve alongside brown rice.'], nutrition:{kcal:380,protein:33,carbs:39,fat:12,fiber:5,sodium:680}, tags:['High protein','Light','Comforting'], accent:'blue' },
  { id:'korean-mackerel-kimchi-braise', sourceId:'slice4-13', name:'ปลาซาบะตุ๋นกิมจิ', englishName:'Korean Mackerel and Kimchi Braise', category:'High protein', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Mackerel fillets',amount:'260 g'},{item:'Kimchi, chopped',amount:'180 g'},{item:'Daikon, sliced',amount:'200 g'},{item:'Low-sodium stock',amount:'250 ml'},{item:'Gochujang',amount:'1 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Layer daikon and kimchi in a wide pan and pour in the stock.','Stir gochujang and garlic into the liquid, then simmer until the daikon begins to soften.','Nestle in the mackerel, cover and simmer until the fish flakes easily and the sauce is reduced.','Finish with spring onion and serve with brown rice.'], nutrition:{kcal:462,protein:29,carbs:46,fat:18,fiber:6,sodium:910}, tags:['High protein','Omega-rich','Comforting'], accent:'red' },
  {"id":"korean-tofu-egg-pancakes","sourceId":"slice4-14","name":"แพนเค้กเต้าหู้ไข่แบบเกาหลี","englishName":"Korean Tofu and Egg Pancakes","category":"Plant-forward","cuisine":"Korean","servings":2,"prepMinutes":30,"cookMinutes":25,"ingredients":[{"item":"Firm tofu, pressed and crumbled","amount":"300 g"},{"item":"Eggs","amount":"2"},{"item":"Mushrooms, finely chopped","amount":"150 g"},{"item":"Zucchini, grated and squeezed dry","amount":"1 medium"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Gochujang","amount":"1 tbsp"},{"item":"Sesame oil","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Oats, finely ground","amount":"30 g"}],"instructions":["Press tofu in a clean cloth for 15 minutes and squeeze zucchini very dry. Dry-fry chopped mushrooms until all released liquid evaporates; cool.","Mix crumbled tofu, zucchini, mushrooms, eggs, ground oats and half the spring onion. Rest 10 minutes so oats absorb moisture.","Brush a non-stick pan with sesame oil in batches. Make twelve small 6 cm pancakes, 1 cm thick; cook over medium-low heat for 4–5 minutes per side. Turn only when the base is firm; centres must reach 72°C.","Mix gochujang with 1 tablespoon warm water. Serve six pancakes per person with brown rice, dipping sauce and remaining spring onion."],"nutrition":{"kcal":474,"protein":32,"carbs":49,"fat":18,"fiber":7,"sodium":320},"tags":["Vegetarian","Plant protein","Balanced"],"accent":"aqua"},
  { id:'korean-gochujang-eggplant-chickpeas', sourceId:'slice4-15', name:'มะเขือยาวโคชูจังกับถั่วชิกพี', englishName:'Korean Gochujang Eggplant with Chickpeas', category:'Plant-forward', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Eggplant, sliced',amount:'350 g'},{item:'Chickpeas, rinsed',amount:'1 cup'},{item:'Gochujang',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'2 tsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spinach',amount:'100 g'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Roast the eggplant at 220°C until the edges are browned and the flesh is tender, about 15 minutes.','Whisk gochujang, soy sauce, garlic and sesame oil, then toss with the hot eggplant and chickpeas.','Wilt the spinach in the warm pan or tray and fold it through.','Serve over brown rice while the glaze is still glossy.'], nutrition:{kcal:410,protein:17,carbs:63,fat:12,fiber:13,sodium:760}, tags:['Vegan','Plant protein','Fiber-rich'], accent:'violet' },
  {"id":"korean-beef-cucumber-noodle-salad","sourceId":"slice4-16","name":"สลัดเส้นหมี่เนื้อแตงกวาเกาหลี","englishName":"Korean Beef and Cucumber Noodle Salad","category":"Light bowls","cuisine":"Korean","servings":2,"prepMinutes":18,"cookMinutes":10,"ingredients":[{"item":"Lean beef strips","amount":"220 g"},{"item":"Rice vermicelli, dry","amount":"100 g"},{"item":"Cucumber, julienned","amount":"1 small"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Romaine lettuce, chopped","amount":"120 g"},{"item":"Reduced-sodium soy sauce","amount":"1½ tbsp"},{"item":"Rice vinegar","amount":"2 tbsp"},{"item":"Sesame oil","amount":"2 tsp"},{"item":"Garlic, minced","amount":"1 clove"},{"item":"Sesame seeds","amount":"1 tsp"}],"instructions":["Cook the rice vermicelli according to the packet, rinse under cold water and drain well.","Whisk soy sauce, rice vinegar, sesame oil and garlic with 3 tablespoons water to make enough dressing to coat the drained noodles evenly.","Sear the beef in a hot pan until browned and cooked through, then rest briefly.","Toss noodles, cucumber, carrot and lettuce with half the dressing, top with beef and finish with the remaining dressing and sesame."],"nutrition":{"kcal":430,"protein":29,"carbs":50,"fat":12,"fiber":4,"sodium":480},"tags":["High protein","Light","Quick"],"accent":"gold"},
  { id:'chinese-beef-tomato-rice-noodle-soup', sourceId:'slice4-17', name:'ก๋วยเตี๋ยวน้ำเนื้อมะเขือเทศจีน', englishName:'Chinese Beef and Tomato Rice Noodle Soup', category:'Quick meals', cuisine:'Chinese', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Lean beef strips',amount:'240 g'},{item:'Rice noodles, dry',amount:'120 g'},{item:'Tomatoes, chopped',amount:'300 g'},{item:'Low-sodium stock',amount:'650 ml'},{item:'Bok choy, chopped',amount:'180 g'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Coriander leaves, chopped',amount:'¼ cup'},{item:'Sesame oil',amount:'1 tsp'}], instructions:['Simmer the stock with tomatoes and ginger until the tomatoes soften and the broth tastes rounded.','Cook the rice noodles separately according to the packet and drain.','Add bok choy and beef to the broth and simmer until the beef is cooked through and the greens are tender.','Season with soy sauce and sesame oil, then divide over the noodles and finish with coriander.'], nutrition:{kcal:435,protein:32,carbs:60,fat:9,fiber:6,sodium:720}, tags:['High protein','Comforting','Quick'], accent:'coral' },
  { id:'chinese-hot-sour-tofu-soup', sourceId:'slice4-18', name:'ซุปเต้าหู้เผ็ดเปรี้ยวจีน', englishName:'Chinese Hot-and-Sour Tofu Soup', category:'Plant-forward', cuisine:'Chinese', servings:2, prepMinutes:10, cookMinutes:16, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Mushrooms, sliced',amount:'180 g'},{item:'Low-sodium vegetable stock',amount:'600 ml'},{item:'Eggs',amount:'1'},{item:'Rice vinegar',amount:'2 tbsp'},{item:'Chilli bean paste',amount:'1 tbsp'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Spinach',amount:'100 g'},{item:'Spring onion, sliced',amount:'2 stalks'}], instructions:['Simmer the vegetable stock with ginger, chilli bean paste and mushrooms until the mushrooms are tender.','Add tofu and spinach and warm through without breaking the tofu.','Stir the soup in one direction while slowly pouring in the beaten egg, then season with rice vinegar.','Finish with spring onion and serve hot.'], nutrition:{kcal:285,protein:22,carbs:22,fat:12,fiber:5,sodium:820}, tags:['Vegetarian','Light','Comforting'], accent:'red' },
  {"id":"chinese-chicken-mushroom-congee","sourceId":"slice4-19","name":"โจ๊กไก่เห็ดแบบจีน","englishName":"Chinese Chicken and Mushroom Congee","category":"Light bowls","cuisine":"Chinese","servings":2,"prepMinutes":10,"cookMinutes":55,"ingredients":[{"item":"Skinless chicken breast, minced","amount":"240 g"},{"item":"Jasmine rice, dry","amount":"100 g"},{"item":"Low-sodium stock","amount":"1000 ml"},{"item":"Shiitake mushrooms, sliced","amount":"160 g"},{"item":"Ginger, julienned","amount":"1 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Sesame oil","amount":"1 tsp"}],"instructions":["Rinse the dry rice, drain and pulse briefly to crack the grains. Bring stock and ginger to a boil, add rice and simmer partially covered for 35–45 minutes, stirring often until the grains break down into a thick porridge. Add boiling water in 50 ml increments if needed.","Sear shiitake in sesame oil until browned, reserving half for the topping. Mix chicken mince with soy sauce.","Stir seasoned mince gradually into the gently bubbling porridge, breaking it into fine strands; add half the mushrooms and cook for 6–8 minutes until chicken reaches 74°C.","Divide between bowls and top with reserved browned shiitake and spring onion."],"nutrition":{"kcal":410,"protein":35,"carbs":51,"fat":7,"fiber":3,"sodium":820},"tags":["High protein","Comforting","Light"],"accent":"blue"},
  {"id":"chinese-sesame-eggplant-rice-noodles","sourceId":"slice4-20","name":"เส้นข้าวมะเขือยาวซอสงาถั่วลิสง","englishName":"Chinese Sesame-Peanut Eggplant Rice Noodles","category":"Plant-forward","cuisine":"Chinese","servings":2,"prepMinutes":15,"cookMinutes":16,"ingredients":[{"item":"Eggplant, sliced","amount":"300 g"},{"item":"Rice noodles, dry","amount":"120 g"},{"item":"Mushrooms, sliced","amount":"150 g"},{"item":"Natural peanut butter","amount":"3 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Rice vinegar","amount":"2 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Sesame seeds","amount":"1 tsp"},{"item":"Sesame oil","amount":"2 tsp"}],"instructions":["Cook the rice noodles according to the packet, rinse briefly and drain; reserve 100 ml cooking water.","Pan-sear eggplant in sesame oil until browned; add 3 tablespoons water, cover for 5 minutes until soft, then uncover and cook mushrooms and garlic until excess liquid evaporates.","Whisk peanut butter, soy sauce and rice vinegar with 60 ml warm noodle water into a pourable sauce.","Toss noodles and cooked vegetables with sauce for 1 minute. Add remaining noodle water a tablespoon at a time until every strand is glossy with no dry clumps or watery puddle. Top with cucumber and sesame seeds."],"nutrition":{"kcal":484,"protein":15,"carbs":69,"fat":18,"fiber":8,"sodium":280},"tags":["Vegan","Plant protein","Balanced"],"accent":"gold"},
  { id:'chinese-steamed-chicken-cabbage-rolls', sourceId:'slice4-21', name:'กะหล่ำปลีห่อไก่นึ่งแบบจีน', englishName:'Chinese Steamed Chicken Cabbage Rolls', category:'High protein', cuisine:'Chinese', servings:2, prepMinutes:20, cookMinutes:18, ingredients:[{item:'Lean chicken mince',amount:'260 g'},{item:'Cabbage leaves',amount:'10 leaves'},{item:'Mushrooms, sliced',amount:'120 g'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Blanch the cabbage leaves briefly until flexible, then drain and pat dry.','Mix chicken mince with mushrooms, ginger, soy sauce and half the spring onion.','Place the filling in the cabbage leaves, roll tightly and steam until the centre reaches 74°C, about 15–18 minutes.','Finish with sesame oil and the remaining spring onion, and serve with brown rice.'], nutrition:{kcal:390,protein:35,carbs:43,fat:12,fiber:5,sodium:680}, tags:['High protein','Light','Meal prep'], accent:'aqua' },
  {"id":"vietnamese-tofu-sandwich","sourceId":"slice4-22","name":"แซนด์วิชเต้าหู้เวียดนาม","englishName":"Vietnamese Tofu Sandwich","category":"Quick meals","cuisine":"Vietnamese","servings":2,"prepMinutes":20,"cookMinutes":10,"ingredients":[{"item":"Firm tofu, sliced","amount":"280 g"},{"item":"Whole-wheat bread","amount":"4 slices"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Carrot, julienned","amount":"1 medium"},{"item":"Daikon, julienned","amount":"150 g"},{"item":"Rice vinegar","amount":"2 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Coriander leaves","amount":"½ cup"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Natural peanut butter","amount":"2 tbsp"}],"instructions":["Toss carrot and daikon with rice vinegar and leave for 10 minutes to quick-pickle; drain.","Brush tofu with soy sauce and sear in the oil until golden on both sides.","Whisk peanut butter with lime juice and 1 tablespoon water into a spread. Toast the four bread slices and spread evenly.","Make two sandwiches using two slices each, filled with cucumber, tofu, drained pickles and coriander. Close and serve immediately."],"nutrition":{"kcal":463,"protein":30,"carbs":43,"fat":21,"fiber":10,"sodium":570},"tags":["Vegan","Quick","Plant protein"],"accent":"lime"},
  {"id":"vietnamese-lemongrass-fish-noodles","sourceId":"slice4-23","name":"เส้นหมี่ปลาตะไคร้สมุนไพรเวียดนาม","englishName":"Vietnamese Lemongrass Fish Noodles","category":"Light bowls","cuisine":"Vietnamese","servings":2,"prepMinutes":18,"cookMinutes":12,"ingredients":[{"item":"White fish fillets","amount":"300 g"},{"item":"Rice vermicelli, dry","amount":"100 g"},{"item":"Lemongrass, minced","amount":"2 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Fish sauce, divided","amount":"1 tbsp"},{"item":"Lime juice","amount":"2 tbsp"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Mint leaves","amount":"½ cup"},{"item":"Coriander leaves","amount":"½ cup"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Brown sugar","amount":"2 tsp"}],"instructions":["Coat fish with lemongrass, garlic and 1 teaspoon fish sauce; rest for 10 minutes.","Cook vermicelli according to the packet, rinse cold and drain. Dissolve sugar in 3 tablespoons warm water, then add lime juice and remaining 2 teaspoons fish sauce.","Pan-sear fish in the oil until browned and the centre reaches 63°C; flake into large pieces.","Toss noodles, cucumber, mint and coriander with all the savory-sour dressing and top with fish."],"nutrition":{"kcal":371,"protein":32,"carbs":51,"fat":4,"fiber":2,"sodium":680},"tags":["High protein","Light","Dairy-free"],"accent":"aqua"},
  {"id":"vietnamese-pork-lemongrass-skillet","sourceId":"slice4-24","name":"หมูผัดตะไคร้เวียดนาม","englishName":"Vietnamese Lemongrass Pork Skillet","category":"Quick meals","cuisine":"Vietnamese","servings":2,"prepMinutes":15,"cookMinutes":14,"ingredients":[{"item":"Lean pork tenderloin, thinly sliced","amount":"280 g"},{"item":"Lemongrass, minced","amount":"2 tbsp"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Fish sauce","amount":"1½ tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Green beans","amount":"180 g"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Neutral oil","amount":"1 tsp"},{"item":"Brown sugar","amount":"2 tsp"},{"item":"Ground black pepper","amount":"½ tsp"}],"instructions":["Mix fish sauce, lime juice, black pepper and 3 tablespoons water. Blanch green beans until crisp-tender and drain.","Heat sugar with 1 tablespoon water in a wide pan until amber. Carefully add the fish-sauce mixture to stop the caramel cooking.","Add oil, lemongrass, garlic and pork; simmer and toss for 6–8 minutes until pork is cooked through and the caramel-pepper glaze clings. Add beans for the final 2 minutes.","Serve the glossy lemongrass caramel pork and beans with fresh cucumber and brown rice."],"nutrition":{"kcal":377,"protein":36,"carbs":41,"fat":8,"fiber":5,"sodium":380},"tags":["High protein","Quick","Balanced"],"accent":"coral"},
  {"id":"vietnamese-eggplant-peanut-herb-salad","sourceId":"slice4-25","name":"ยำมะเขือยาวถั่วลิสงสมุนไพรเวียดนาม","englishName":"Vietnamese Eggplant Peanut Herb Salad","category":"Plant-forward","cuisine":"Vietnamese","servings":2,"prepMinutes":18,"cookMinutes":15,"ingredients":[{"item":"Eggplant, sliced","amount":"300 g"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Mint leaves","amount":"½ cup"},{"item":"Coriander leaves","amount":"½ cup"},{"item":"Roasted peanuts, chopped","amount":"2 tbsp"},{"item":"Lime juice","amount":"2 tbsp"},{"item":"Reduced-sodium soy sauce","amount":"1 tbsp"},{"item":"Garlic, minced","amount":"1 clove"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Spring onion, finely sliced","amount":"2 stalks"},{"item":"Neutral oil","amount":"2 tsp"}],"instructions":["Grill eggplant over medium-high heat for 10–15 minutes, turning until the flesh is completely soft and the surface is charred; tear into long strips.","Whisk lime juice, soy sauce and garlic. Warm oil in a small pan, add spring onion and sizzle for 20 seconds, then remove from heat.","Arrange warm eggplant on a platter, spoon over the scallion oil and lime-soy dressing, then add cucumber, mint and coriander.","Scatter peanuts over the dressed eggplant and serve with brown rice."],"nutrition":{"kcal":278,"protein":8,"carbs":42,"fat":10,"fiber":8,"sodium":260},"tags":["Vegan","Fiber-rich","Light"],"accent":"green"},
  {"id":"turkish-red-lentil-soup","sourceId":"slice4-26","name":"ซุปถั่วเลนทิลแดงสไตล์ตุรกี","englishName":"Turkish-Style Red Lentil Soup","category":"Plant-forward","cuisine":"Mediterranean","servings":2,"prepMinutes":12,"cookMinutes":32,"ingredients":[{"item":"Red lentils, dry, rinsed","amount":"120 g"},{"item":"Tomatoes, chopped","amount":"300 g"},{"item":"Onion, chopped","amount":"1 medium"},{"item":"Carrot, diced","amount":"1 medium"},{"item":"Low-sodium vegetable stock","amount":"600 ml"},{"item":"Cumin","amount":"1 tsp"},{"item":"Paprika","amount":"1 tsp"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Whole-wheat bread","amount":"2 slices"}],"instructions":["Warm olive oil and soften onion and carrot for 5 minutes.","Add cumin and paprika and stir for 30 seconds.","Add tomatoes, rinsed dry red lentils and vegetable stock. Simmer partially covered for 20–25 minutes until lentils collapse, stirring often. Add water in 50 ml increments if too thick; blend half the soup and return it to the pot.","Finish with lemon juice and serve with toasted whole-wheat bread."],"nutrition":{"kcal":397,"protein":23,"carbs":68,"fat":5,"fiber":13,"sodium":470},"tags":["Vegan","Fiber-rich","Comforting"],"accent":"gold"},
  { id:'moroccan-chickpea-eggplant-stew', sourceId:'slice4-27', name:'สตูว์ถั่วชิกพีมะเขือยาวสไตล์โมร็อกโก', englishName:'Moroccan Chickpea and Eggplant Stew', category:'Plant-forward', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:28, ingredients:[{item:'Chickpeas, rinsed',amount:'1½ cups'},{item:'Eggplant, cubed',amount:'300 g'},{item:'Tomatoes, chopped',amount:'300 g'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Onion, diced',amount:'1 medium'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Cumin',amount:'1 tsp'},{item:'Paprika',amount:'1 tsp'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat couscous, cooked',amount:'150 g'}], instructions:['Warm the olive oil and brown the eggplant, onion and bell pepper until the edges are caramelized.','Add garlic, cumin and paprika and stir for 30 seconds.','Add tomatoes and chickpeas and simmer uncovered until the eggplant is tender and the sauce is thick.','Serve over couscous and spoon the sauce around the grains.'], nutrition:{kcal:435,protein:16,carbs:68,fat:11,fiber:15,sodium:420}, tags:['Vegan','Fiber-rich','Meal prep'], accent:'red' },
  {"id":"mediterranean-lentil-stuffed-peppers","sourceId":"slice4-28","name":"พริกหวานยัดไส้ถั่วเลนทิลเมดิเตอร์เรเนียน","englishName":"Mediterranean Lentil-Stuffed Peppers","category":"Plant-forward","cuisine":"Mediterranean","servings":2,"prepMinutes":18,"cookMinutes":30,"ingredients":[{"item":"Green lentils, cooked","amount":"1½ cups"},{"item":"Bell peppers, halved","amount":"2 medium"},{"item":"Cooked quinoa","amount":"1 cup"},{"item":"Tomatoes, chopped","amount":"200 g"},{"item":"Onion, diced","amount":"1 small"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Dried oregano","amount":"1 tsp"},{"item":"Feta cheese, vegetarian-certified, crumbled","amount":"40 g"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Parsley, chopped","amount":"½ cup"},{"item":"Lemon juice","amount":"1 tbsp"}],"instructions":["Roast pepper halves cut-side up at 200°C for 10 minutes.","Soften onion in olive oil for 5 minutes, add garlic and oregano for 30 seconds, then tomatoes; cook until excess juice evaporates.","Fold in lentils and quinoa, keeping the grains separate. Fill peppers and bake for 18–20 minutes until tender and hot through.","Fold parsley and lemon juice into the exposed stuffing and finish with vegetarian feta; rest for 3 minutes."],"nutrition":{"kcal":445,"protein":24,"carbs":69,"fat":10,"fiber":20,"sodium":250},"tags":["Vegetarian","Fiber-rich","Meal prep"],"accent":"coral"},
  { id:'mediterranean-tuna-stuffed-tomatoes', sourceId:'slice4-29', name:'มะเขือเทศยัดไส้ทูน่าเมดิเตอร์เรเนียน', englishName:'Mediterranean Tuna-Stuffed Tomatoes', category:'Light bowls', cuisine:'Mediterranean', servings:2, prepMinutes:18, cookMinutes:0, ingredients:[{item:'Tuna in spring water, drained',amount:'200 g'},{item:'Tomatoes, large',amount:'4 medium'},{item:'Chickpeas, rinsed',amount:'½ cup'},{item:'Cucumber, diced',amount:'1 small'},{item:'Greek yogurt',amount:'3 tbsp'},{item:'Lemon juice',amount:'1 tbsp'},{item:'Parsley, chopped',amount:'½ cup'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat bread',amount:'2 slices'}], instructions:['Slice the tops from the tomatoes and scoop out the watery centres, leaving the shells intact.','Mix tuna, chickpeas, cucumber, yogurt, lemon juice and parsley.','Fill the tomatoes and drizzle with olive oil.','Serve with toasted whole-wheat bread.'], nutrition:{kcal:390,protein:35,carbs:40,fat:10,fiber:9,sodium:520}, tags:['High protein','No-cook','Light'], accent:'lime' },
  {"id":"greek-lemon-chickpea-egg-soup","sourceId":"slice4-30","name":"ซุปถั่วชิกพีไข่เลมอนแบบกรีก","englishName":"Greek Lemon Chickpea and Egg Soup","category":"Light bowls","cuisine":"Mediterranean","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"item":"Chickpeas, rinsed","amount":"1½ cups"},{"item":"Eggs","amount":"2"},{"item":"Low-sodium vegetable stock","amount":"700 ml"},{"item":"Spinach","amount":"120 g"},{"item":"Lemon juice","amount":"3 tbsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Onion, chopped","amount":"1 small"},{"item":"Garlic, minced","amount":"2 cloves"}],"instructions":["Simmer onion, garlic, chickpeas and vegetable stock for 12 minutes. Add spinach and cook until wilted.","Whisk eggs with lemon juice; gradually whisk in two ladles of hot broth to temper the eggs.","Remove the pot from heat and stir in tempered eggs. Return to low heat, stirring continuously until the soup reaches 72°C on a thermometer and lightly coats a spoon. Do not boil: the broth should be creamy, without egg ribbons.","Serve over warm brown rice immediately."],"nutrition":{"kcal":380,"protein":20,"carbs":52,"fat":9,"fiber":12,"sodium":420},"tags":["Vegetarian","Comforting","Fiber-rich"],"accent":"gold"},
  { id:'italian-chicken-cacciatore', sourceId:'slice4-31', name:'ไก่คัชชาโตเร่อิตาเลียน', englishName:'Italian Chicken Cacciatore', category:'High protein', cuisine:'Italian', servings:2, prepMinutes:15, cookMinutes:30, ingredients:[{item:'Skinless chicken thighs, boneless',amount:'300 g'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Onion, sliced',amount:'1 medium'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Dried oregano',amount:'1 tsp'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat penne, dry',amount:'150 g'}], instructions:['Warm the oil in a wide pan and brown the chicken on both sides; transfer to a clean plate.','Cook onion, bell pepper and mushrooms until the edges soften, then add garlic and oregano.','Add tomatoes and return the chicken; cover and simmer until the chicken is fully cooked and the sauce is thick.','Cook the penne separately, drain and serve with the chicken and sauce.'], nutrition:{kcal:590,protein:39,carbs:66,fat:18,fiber:10,sodium:520}, tags:['High protein','Comforting','Meal prep'], accent:'red' },
  {"id":"italian-eggplant-parmigiana-light","sourceId":"slice4-32","name":"พาร์มิจานามะเขือยาวแบบเบา","englishName":"Lighter Italian Eggplant Parmigiana","category":"Plant-forward","cuisine":"Italian","servings":2,"prepMinutes":18,"cookMinutes":30,"ingredients":[{"item":"Eggplant, sliced","amount":"400 g"},{"item":"Tomatoes, chopped","amount":"400 g"},{"item":"Whole-wheat bread, crumbed","amount":"2 slices"},{"item":"Vegetarian-certified hard cheese, grated (microbial rennet)","amount":"30 g"},{"item":"Basil leaves","amount":"½ cup"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Rocket leaves","amount":"80 g"}],"instructions":["Roast the eggplant at 220°C until browned and tender, turning once.","Simmer tomatoes with garlic and half the basil for 8 minutes until thick.","Layer tomato sauce, eggplant, bread crumbs and vegetarian hard cheese in a small baking dish and bake until bubbling and golden.","Rest for 5 minutes and serve with rocket leaves and the remaining basil."],"nutrition":{"kcal":345,"protein":16,"carbs":47,"fat":10,"fiber":12,"sodium":540},"tags":["Vegetarian","Fiber-rich","Balanced"],"accent":"violet"},
  { id:'italian-salmon-spinach-pasta', sourceId:'slice4-33', name:'พาสต้าแซลมอนผักโขมซอสโยเกิร์ต', englishName:'Italian Salmon and Spinach Pasta', category:'High protein', cuisine:'Italian', servings:2, prepMinutes:10, cookMinutes:18, ingredients:[{item:'Salmon fillets',amount:'260 g'},{item:'Whole-wheat penne, dry',amount:'150 g'},{item:'Spinach',amount:'120 g'},{item:'Greek yogurt',amount:'3 tbsp'},{item:'Lemon juice',amount:'1 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Olive oil',amount:'1 tsp'},{item:'Green peas',amount:'½ cup'}], instructions:['Cook the penne until just tender and reserve ½ cup of the cooking water.','Pan-sear the salmon in the oil until it flakes easily, then rest and break into large pieces.','Warm garlic, peas and spinach in the pan until the spinach wilts; turn off the heat and stir in yogurt and lemon juice.','Toss with pasta and enough cooking water to make a light sauce, then fold in the salmon.'], nutrition:{kcal:575,protein:37,carbs:63,fat:18,fiber:10,sodium:390}, tags:['High protein','Omega-rich','Balanced'], accent:'aqua' },
  {"id":"italian-mushroom-barley-risotto","sourceId":"slice4-34","name":"ริซอตโตข้าวบาร์เลย์เห็ด","englishName":"Italian Mushroom Barley Risotto","category":"Plant-forward","cuisine":"Italian","servings":2,"prepMinutes":12,"cookMinutes":50,"ingredients":[{"item":"Pearl barley, dry","amount":"150 g"},{"item":"Mixed mushrooms, sliced","amount":"300 g"},{"item":"Low-sodium vegetable stock","amount":"700 ml"},{"item":"Onion, diced","amount":"1 small"},{"item":"Spinach","amount":"100 g"},{"item":"Vegetarian-certified hard cheese, grated (microbial rennet)","amount":"25 g"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Lemon juice","amount":"1 tbsp"}],"instructions":["Use half the olive oil to brown mushrooms in a wide pan in batches for 6–8 minutes; remove and reserve.","Soften onion in remaining oil, add barley and toast for 2 minutes. Add hot vegetable stock a ladle at a time, stirring frequently.","Simmer for 30–40 minutes until barley is tender with a slight chew, adding hot water if stock runs out. Return mushrooms for the last 5 minutes and fold in spinach until wilted.","Turn off heat and stir in vegetarian hard cheese and lemon juice; rest 2 minutes. The mixture should spread gently when spooned, not sit in a dry mound."],"nutrition":{"kcal":450,"protein":18,"carbs":70,"fat":11,"fiber":12,"sodium":520},"tags":["Vegetarian","Fiber-rich","Comforting"],"accent":"gold"},
  { id:'mexican-fish-tacos-cabbage', sourceId:'slice4-35', name:'ทาโก้ปลาและกะหล่ำปลีเม็กซิกัน', englishName:'Mexican Fish Tacos with Cabbage', category:'Quick meals', cuisine:'Mexican', servings:2, prepMinutes:15, cookMinutes:14, ingredients:[{item:'White fish fillets',amount:'300 g'},{item:'Whole-wheat tortillas',amount:'4'},{item:'Cabbage, shredded',amount:'200 g'},{item:'Tomato salsa',amount:'½ cup'},{item:'Greek yogurt',amount:'3 tbsp'},{item:'Lime juice',amount:'2 tbsp'},{item:'Ground cumin',amount:'1 tsp'},{item:'Neutral oil',amount:'1 tsp'}], instructions:['Rub the fish with cumin and half the lime juice, then pan-sear in the oil until opaque and flaky.','Mix yogurt with the remaining lime juice for a quick crema.','Warm the tortillas and fill them with cabbage, fish, salsa and crema.','Serve immediately so the cabbage stays crisp.'], nutrition:{kcal:448,protein:36,carbs:49,fat:12,fiber:8,sodium:570}, tags:['High protein','Quick','Balanced'], accent:'lime' },
  { id:'mexican-huevos-rancheros', sourceId:'slice4-36', name:'ฮูเอโวส รันเชโรสแบบเบา', englishName:'Lighter Mexican Huevos Rancheros', category:'Quick meals', cuisine:'Mexican', servings:2, prepMinutes:10, cookMinutes:14, ingredients:[{item:'Eggs',amount:'4'},{item:'Black beans, rinsed',amount:'1 cup'},{item:'Tomato salsa',amount:'1 cup'},{item:'Whole-wheat tortillas',amount:'4'},{item:'Avocado, sliced',amount:'½'},{item:'Lime juice',amount:'1 tbsp'},{item:'Coriander leaves, chopped',amount:'¼ cup'},{item:'Olive oil',amount:'1 tsp'}], instructions:['Warm the salsa and black beans in a wide pan until bubbling gently.','Make four wells, crack in the eggs, cover and cook until the whites are set and the yolks reach the desired doneness.','Warm the tortillas and top with the eggs, beans and salsa.','Finish with avocado, lime juice and coriander.'], nutrition:{kcal:500,protein:24,carbs:56,fat:19,fiber:14,sodium:690}, tags:['Vegetarian','Balanced','Quick'], accent:'coral' },
  { id:'mexican-black-bean-stuffed-peppers', sourceId:'slice4-37', name:'พริกหวานยัดไส้ถั่วดำเม็กซิกัน', englishName:'Mexican Black Bean Stuffed Peppers', category:'Plant-forward', cuisine:'Mexican', servings:2, prepMinutes:18, cookMinutes:28, ingredients:[{item:'Black beans, rinsed',amount:'1½ cups'},{item:'Bell peppers, halved',amount:'2 medium'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Corn kernels',amount:'½ cup'},{item:'Tomato salsa',amount:'½ cup'},{item:'Onion, diced',amount:'1 small'},{item:'Ground cumin',amount:'1 tsp'},{item:'Chili powder',amount:'½ tsp'},{item:'Lime juice',amount:'1 tbsp'},{item:'Pumpkin seeds',amount:'1 tbsp'}], instructions:['Roast the pepper halves cut-side up at 200°C for 10 minutes.','Mix black beans, rice, corn, salsa, onion, cumin and chili powder.','Fill the peppers and bake until the peppers are tender and the filling is hot, about 18 minutes.','Finish with lime juice and pumpkin seeds.'], nutrition:{kcal:460,protein:18,carbs:70,fat:11,fiber:17,sodium:620}, tags:['Vegan','Fiber-rich','Meal prep'], accent:'red' },
  {"id":"mexican-chicken-enchilada-quinoa-bake","sourceId":"slice4-38","name":"ควินัวไก่อบซอสเอนชิลาดา","englishName":"Mexican Chicken Enchilada Quinoa Bake","category":"High protein","cuisine":"Mexican","servings":2,"prepMinutes":18,"cookMinutes":40,"ingredients":[{"item":"Skinless chicken breast, diced","amount":"260 g"},{"item":"Cooked quinoa","amount":"1 cup"},{"item":"Black beans, rinsed","amount":"1 cup"},{"item":"Tomatoes, crushed","amount":"400 g"},{"item":"Corn kernels","amount":"½ cup"},{"item":"Bell pepper, diced","amount":"1 medium"},{"item":"Onion, diced","amount":"1 small"},{"item":"Chili powder","amount":"2 tsp"},{"item":"Ground cumin","amount":"1 tsp"},{"item":"Lime juice","amount":"1 tbsp"},{"item":"Coriander leaves","amount":"½ cup"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Dried oregano","amount":"1 tsp"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Warm olive oil, cook garlic, chili powder, cumin and oregano for 30 seconds, then add crushed tomatoes and 100 ml water. Simmer for 10 minutes and blend into a smooth enchilada-style sauce.","In a non-stick ovenproof pan, cook chicken, onion and bell pepper with 2 tablespoons water until the chicken exterior is opaque and vegetables soften.","Fold in quinoa, black beans, corn and all the smooth sauce. Bake uncovered at 200°C for 18–22 minutes until bubbling, lightly crusted at the edges and chicken reaches 74°C.","Rest for 5 minutes so the bake holds together when spooned. Finish with lime juice and coriander; no cheese topping."],"nutrition":{"kcal":528,"protein":46,"carbs":67,"fat":10,"fiber":17,"sodium":180},"tags":["High protein","Fiber-rich","Meal prep"],"accent":"gold"},
  { id:'latin-lentil-picadillo-tostadas', sourceId:'slice4-39', name:'โตสตาดาถั่วเลนทิลพิคาดิลโล', englishName:'Latin Lentil Picadillo Tostadas', category:'Plant-forward', cuisine:'Mexican', servings:2, prepMinutes:15, cookMinutes:18, ingredients:[{item:'Green lentils, cooked',amount:'1½ cups'},{item:'Whole-wheat tortillas',amount:'4'},{item:'Tomato salsa',amount:'½ cup'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Onion, diced',amount:'1 small'},{item:'Ground cumin',amount:'1 tsp'},{item:'Chili powder',amount:'½ tsp'},{item:'Avocado, sliced',amount:'½'},{item:'Lettuce, shredded',amount:'120 g'},{item:'Lime juice',amount:'1 tbsp'}], instructions:['Bake the tortillas directly on an oven rack at 190°C until crisp and flat, about 6–8 minutes.','Cook onion and bell pepper until browned at the edges, then add lentils, salsa, cumin and chili powder and simmer until thick.','Spread the lentil picadillo over the crisp tortillas and top with lettuce and avocado.','Finish with lime juice and serve while the tostadas are crisp.'], nutrition:{kcal:450,protein:18,carbs:68,fat:13,fiber:16,sodium:560}, tags:['Vegan','Fiber-rich','Balanced'], accent:'aqua' },
  {"id":"indian-red-lentil-coconut-dal","sourceId":"slice4-40","name":"ดาลถั่วเลนทิลแดงกะทิแบบอินเดีย","englishName":"Indian-Style Red Lentil Coconut Dal","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":12,"cookMinutes":35,"ingredients":[{"item":"Red lentils, dry, rinsed","amount":"120 g"},{"item":"Light coconut milk","amount":"200 ml"},{"item":"Tomatoes, chopped","amount":"300 g"},{"item":"Spinach","amount":"150 g"},{"item":"Onion, diced","amount":"1 medium"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ginger, minced","amount":"1 tbsp"},{"item":"Curry powder","amount":"2 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Lime juice","amount":"1 tbsp"}],"instructions":["Soften onion, garlic and ginger with 3 tablespoons water in a non-stick pot for 5 minutes; add curry powder and stir for 30 seconds.","Add rinsed dry red lentils, tomatoes and 400 ml water. Simmer partially covered for 20–25 minutes, stirring often, until lentils collapse into a soft dal.","Stir in coconut milk and simmer for 5 minutes; fold in spinach until wilted. Add water a tablespoon at a time if needed for a loose, spoonable dal.","Finish with lime juice and serve with brown rice."],"nutrition":{"kcal":486,"protein":23,"carbs":80,"fat":10,"fiber":13,"sodium":100},"tags":["Vegan","Plant protein","Fiber-rich"],"accent":"gold"},
  {"id":"indian-chickpea-spinach-curry","sourceId":"slice4-41","name":"แกงถั่วชิกพีผักโขมแบบอินเดีย","englishName":"Indian-Style Chickpea and Spinach Curry","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":12,"cookMinutes":22,"ingredients":[{"item":"Chickpeas, rinsed","amount":"1½ cups"},{"item":"Tomatoes, chopped","amount":"300 g"},{"item":"Spinach","amount":"150 g"},{"item":"Onion, diced","amount":"1 medium"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Ginger, minced","amount":"1 tbsp"},{"item":"Ground cumin","amount":"1 tsp"},{"item":"Paprika","amount":"1 tsp"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Dried chilli flakes","amount":"¼ tsp"}],"instructions":["Soften onion, garlic and ginger with 3 tablespoons water in a non-stick pan until lightly golden.","Add cumin, paprika and chilli flakes; stir for 30 seconds, then add tomatoes and simmer uncovered for 10–12 minutes until concentrated and thick.","Fold in chickpeas and simmer for 5 minutes, keeping them whole. Add spinach and cook just until wilted; the tomato masala should cling to the chickpeas, with no coconut broth.","Serve the chunky tomato-spinach chickpea curry beside brown rice."],"nutrition":{"kcal":402,"protein":18,"carbs":75,"fat":5,"fiber":16,"sodium":200},"tags":["Vegan","Plant protein","Fiber-rich"],"accent":"red"},
  {"id":"west-african-peanut-sweet-potato-stew","sourceId":"slice4-42","name":"สตูว์ถั่วชิกพีมันหวานซอสถั่วลิสง","englishName":"West African-Style Peanut, Sweet Potato and Chickpea Stew","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":15,"cookMinutes":28,"ingredients":[{"item":"Chickpeas, rinsed","amount":"1 cup"},{"item":"Sweet potato, cubed","amount":"300 g"},{"item":"Tomatoes, chopped","amount":"300 g"},{"item":"Spinach","amount":"120 g"},{"item":"Onion, diced","amount":"1 medium"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Natural peanut butter","amount":"4 tbsp"},{"item":"Low-sodium vegetable stock","amount":"400 ml"},{"item":"Brown rice, cooked","amount":"1 cup"},{"item":"Ginger, minced","amount":"1 tbsp"},{"item":"Dried chilli flakes","amount":"½ tsp"},{"item":"Lime juice","amount":"1 tbsp"}],"instructions":["Soften onion, garlic, ginger and chilli flakes with 3 tablespoons water, then add tomatoes and simmer for 5 minutes.","Add sweet potato, chickpeas and vegetable stock; simmer for 18–22 minutes until a knife passes easily through the sweet potato.","Whisk peanut butter with a ladle of hot stew, return to the pot and simmer for 3 minutes until the sauce thickens and tastes clearly of peanuts.","Fold in spinach until wilted, turn off heat and add lime juice. Serve over brown rice."],"nutrition":{"kcal":655,"protein":25,"carbs":101,"fat":20,"fiber":19,"sodium":430},"tags":["Vegan","Plant protein","Comforting"],"accent":"gold"},
  { id:'french-chicken-mustard-mushroom-skillet', sourceId:'slice4-43', name:'ไก่เห็ดซอสมัสตาร์ดแบบฝรั่งเศส', englishName:'French-Style Chicken Mustard Mushroom Skillet', category:'High protein', cuisine:'International', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Skinless chicken breast',amount:'280 g'},{item:'Mushrooms, sliced',amount:'250 g'},{item:'Onion, sliced',amount:'1 medium'},{item:'Low-sodium stock',amount:'250 ml'},{item:'Greek yogurt',amount:'3 tbsp'},{item:'Dijon mustard',amount:'1 tbsp'},{item:'Olive oil',amount:'1 tsp'},{item:'Parsley, chopped',amount:'½ cup'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Sear the chicken in the oil until golden on both sides and almost cooked, then transfer to a clean plate.','Cook the onion and mushrooms in the same pan until the mushrooms brown.','Add stock and mustard and simmer until reduced by one third; return the chicken and cook until the centre reaches 74°C.','Turn off the heat, fold in yogurt and parsley, and serve with brown rice.'], nutrition:{kcal:450,protein:42,carbs:42,fat:12,fiber:5,sodium:620}, tags:['High protein','Balanced','Quick'], accent:'aqua' },
  {"id":"international-salmon-oat-cakes","sourceId":"slice4-44","name":"แพตตี้แซลมอนข้าวโอ๊ตกับโยเกิร์ตแตงกวา","englishName":"Salmon Oat Cakes with Cucumber Yogurt","category":"High protein","cuisine":"International","servings":2,"prepMinutes":18,"cookMinutes":18,"ingredients":[{"item":"Salmon fillets","amount":"280 g"},{"item":"Oats","amount":"½ cup"},{"item":"Eggs","amount":"1"},{"item":"Spring onion, sliced","amount":"2 stalks"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Greek yogurt","amount":"3 tbsp"},{"item":"Cucumber, diced","amount":"1 small"},{"item":"Spinach","amount":"100 g"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Bake or steam the salmon until it flakes, cool briefly and flake into a bowl.","Mix salmon with oats, egg, spring onion and half the lemon juice; shape into four firm cakes.","Pan-sear the cakes in the oil until golden on both sides and hot through.","Mix yogurt, cucumber and the remaining lemon juice, wilt the spinach and serve alongside the cakes."],"nutrition":{"kcal":430,"protein":36,"carbs":34,"fat":17,"fiber":6,"sodium":340},"tags":["High protein","Omega-rich","Balanced"],"accent":"coral"},
  {"id":"middle-eastern-falafel-pita","sourceId":"slice4-45","name":"ฟาลาเฟลอบกับพิต้า","englishName":"Baked Falafel with Whole-Wheat Pita","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":35,"cookMinutes":30,"ingredients":[{"item":"Chickpeas, dry, soaked overnight (not cooked)","amount":"120 g"},{"item":"Oats","amount":"2 tbsp"},{"item":"Onion, chopped","amount":"½ cup"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Cumin","amount":"1 tsp"},{"item":"Parsley, chopped","amount":"½ cup"},{"item":"Hummus","amount":"4 tbsp"},{"item":"Whole-wheat pita","amount":"2"},{"item":"Cucumber, sliced","amount":"1 small"},{"item":"Tomatoes, chopped","amount":"120 g"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Soak dry chickpeas in plenty of water for 12–18 hours in the refrigerator; drain and dry thoroughly. Do not use cooked or canned chickpeas. Pat chopped onion dry.","Pulse soaked chickpeas, oats, onion, garlic, cumin and parsley into a fine grit that holds when squeezed, not a smooth paste. Rest for 15 minutes, then shape into eight small 1.5 cm thick discs.","Brush both sides with olive oil and bake on a preheated tray at 210°C for 25–30 minutes, turning halfway, until crisp outside and cooked through with no raw, crunchy centre.","Warm pitas and fill with hummus, cucumber, tomato and four falafel each. Finish with lemon juice. Prep time excludes the overnight soak."],"nutrition":{"kcal":522,"protein":23,"carbs":90,"fat":10,"fiber":16,"sodium":390},"tags":["Vegan","Fiber-rich","Balanced"],"accent":"lime"},
  {"id":"international-mushroom-lentil-shepherds-pie","sourceId":"slice4-46","name":"พายเชพเพิร์ดเห็ดและถั่วเลนทิล","englishName":"Mushroom and Lentil Shepherds Pie","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":20,"cookMinutes":38,"ingredients":[{"item":"Green lentils, cooked","amount":"1½ cups"},{"item":"Mushrooms, sliced","amount":"250 g"},{"item":"Sweet potato, cubed","amount":"500 g"},{"item":"Carrot, diced","amount":"1 medium"},{"item":"Green peas","amount":"½ cup"},{"item":"Onion, diced","amount":"1 medium"},{"item":"Tomatoes, chopped","amount":"200 g"},{"item":"Garlic, minced","amount":"2 cloves"},{"item":"Low-sodium vegetable stock","amount":"250 ml"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Boil the sweet potato until tender, drain and mash until smooth.","Cook onion, carrot, mushrooms and garlic in the oil until browned, then add tomatoes, lentils, peas and vegetable stock and simmer until thick.","Spread the lentil filling in a baking dish and top with the sweet potato mash.","Bake at 200°C until the top is lightly browned and the filling is bubbling, about 18 minutes."],"nutrition":{"kcal":460,"protein":17,"carbs":75,"fat":10,"fiber":18,"sodium":440},"tags":["Vegan","Fiber-rich","Comforting"],"accent":"violet"},
  {"id":"italian-white-bean-bruschetta","sourceId":"slice4-47","name":"บรัสเกตตาถั่วขาวและมะเขือเทศ","englishName":"Italian White Bean and Tomato Bruschetta","category":"Quick meals","cuisine":"Italian","servings":2,"prepMinutes":12,"cookMinutes":8,"ingredients":[{"item":"White beans, rinsed","amount":"1½ cups"},{"item":"Whole-wheat bread","amount":"4 slices"},{"item":"Tomatoes, chopped","amount":"200 g"},{"item":"Basil leaves","amount":"½ cup"},{"item":"Garlic, whole clove, halved","amount":"1 clove"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Vegetarian-certified hard cheese, grated (microbial rennet)","amount":"20 g"},{"item":"Rocket leaves","amount":"80 g"}],"instructions":["Toast bread until crisp and rub each hot slice with the cut face of the halved garlic clove.","Toss white beans, tomatoes, basil, lemon juice and olive oil, lightly crushing some of the beans so the mixture holds together.","Spoon the bean mixture over the toast and finish with vegetarian hard cheese.","Serve with rocket leaves while the bread is crisp."],"nutrition":{"kcal":380,"protein":18,"carbs":54,"fat":10,"fiber":13,"sodium":430},"tags":["Vegetarian","Fiber-rich","Quick"],"accent":"red"},
  { id:'mexican-tofu-chile-tacos', sourceId:'slice4-48', name:'ทาโก้เต้าหู้ถั่วดำและพริก', englishName:'Mexican Tofu and Black Bean Tacos', category:'Plant-forward', cuisine:'Mexican', servings:2, prepMinutes:15, cookMinutes:14, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Whole-wheat tortillas',amount:'4'},{item:'Black beans, rinsed',amount:'½ cup'},{item:'Cabbage, shredded',amount:'180 g'},{item:'Tomato salsa',amount:'½ cup'},{item:'Chili powder',amount:'1 tsp'},{item:'Ground cumin',amount:'1 tsp'},{item:'Lime juice',amount:'2 tbsp'},{item:'Avocado, sliced',amount:'½'},{item:'Neutral oil',amount:'1 tsp'}], instructions:['Pat the tofu dry, toss with chili powder and cumin, and sear in the oil until browned on several sides.','Warm the black beans and salsa together until hot.','Warm the tortillas and fill them with cabbage, tofu, beans, avocado and salsa.','Finish with lime juice and serve immediately.'], nutrition:{kcal:470,protein:24,carbs:58,fat:17,fiber:14,sodium:650}, tags:['Vegan','Plant protein','Quick'], accent:'lime' },
  {"id":"international-chickpea-oat-patties","sourceId":"slice4-49","name":"แพตตี้ถั่วชิกพีข้าวโอ๊ตกับโยเกิร์ตแตงกวา","englishName":"Chickpea Oat Patties with Cucumber Yogurt","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":28,"cookMinutes":16,"ingredients":[{"item":"Chickpeas, rinsed","amount":"1½ cups"},{"item":"Oats","amount":"½ cup"},{"item":"Eggs","amount":"1"},{"item":"Onion, chopped","amount":"½ cup"},{"item":"Carrot, grated","amount":"1 medium"},{"item":"Spinach","amount":"100 g"},{"item":"Dried oregano","amount":"1 tsp"},{"item":"Paprika","amount":"1 tsp"},{"item":"Greek yogurt","amount":"4 tbsp"},{"item":"Cucumber, diced","amount":"1 small"},{"item":"Olive oil","amount":"1 tsp"}],"instructions":["Mash the cooked chickpeas coarsely with oats, egg, onion, grated carrot, oregano and paprika. Rest for 10 minutes for the oats to absorb moisture.","Shape into six broad patties and pan-sear in olive oil over medium-low heat for 4–5 minutes per side until firm and browned and the centres reach 72°C.","Wilt spinach in the same pan with 1 tablespoon water.","Mix yogurt with cucumber and serve with three carrot-oat patties per person and spinach, without pita or hummus."],"nutrition":{"kcal":400,"protein":19,"carbs":54,"fat":12,"fiber":14,"sodium":430},"tags":["Vegetarian","Plant protein","Fiber-rich"],"accent":"aqua"},
  {"id":"international-mushroom-lentil-stuffed-sweet-potato","sourceId":"slice4-50","name":"มันหวานยัดไส้เห็ดและถั่วเลนทิล","englishName":"Mushroom and Lentil Stuffed Sweet Potatoes","category":"Plant-forward","cuisine":"International","servings":2,"prepMinutes":15,"cookMinutes":65,"ingredients":[{"item":"Sweet potato","amount":"2 medium"},{"item":"Green lentils, cooked","amount":"1 cup"},{"item":"Mushrooms, sliced","amount":"250 g"},{"item":"Spinach","amount":"100 g"},{"item":"Onion, diced","amount":"1 small"},{"item":"Tomatoes, chopped","amount":"200 g"},{"item":"Feta cheese, vegetarian-certified, crumbled","amount":"40 g"},{"item":"Olive oil","amount":"1 tsp"},{"item":"Lemon juice","amount":"1 tbsp"},{"item":"Parsley, chopped","amount":"½ cup"}],"instructions":["Pierce sweet potatoes and bake at 200°C for 45–65 minutes, longer if large, until a knife slides through the centre without resistance and the flesh yields when squeezed with an oven glove.","Brown mushrooms and onion in olive oil until their moisture evaporates. Add lentils and spinach and toss until hot and wilted, keeping the lentils intact.","Turn off heat and fold in fresh chopped tomatoes, parsley and lemon juice to make a warm, loose salad rather than a stewed filling.","Split the tender sweet potatoes, fluff their flesh and fill with the warm mushroom-lentil salad. Finish with visible crumbled vegetarian feta."],"nutrition":{"kcal":435,"protein":18,"carbs":61,"fat":13,"fiber":15,"sodium":470},"tags":["Vegetarian","Fiber-rich","Comforting"],"accent":"gold"},
]

